INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (122601, 1, 1, 105, "仲間と夏を楽しむ、夏海の魔法士。自分を変えたいという固い決意で、障害物を無効化して走り続ける。", 0, 0.029, 1, 101, 160, 1, 1.5, 0, 110);
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (122401, 2, 3, 111, "太陽よりも輝く、夏海の元気娘。　持ち前の身体能力で、どんなコースも柔軟に対応し、駆け抜ける。", 0, 0.014, 0, 102, 120, 2, 2.5, 1, 105);
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (122501, 3, 2, 105, "波打ち際に煌めく、夏海の剣士。　日々の鍛錬で鍛えた脚で、長い距離も速度を落とさず走り切る。", 1, 0.017, 0, 103, 350, 3, 2.5, 0, 110);
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (107501, 4, 3, 105, "海の幸に目がない、渚のお姫様。　『王家の装備』の力を解放し、障害物をものともせず前へと進む。", 0, 0.016, 0, 104, 130, 4, 1.5, 1, 110);
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (107601, 5, 1, 105, "海でも主さまをお世話する、白浜の巫女。精霊の力で自身を加速させ、誰よりも速くゴールを目指す。", 0, 0.014, 1, 105, 160, 5, 2.5, 0, 110);
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (107801, 6, 2, 103, "水着姿を恥じらう、ツンデレ猫娘。お得意の魔法で、対戦相手の走りを妨害し、レースを有利に進める。", 1, 0.029, 0, 106, 255, 6, 3.5, 0, 120);
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (110601, 7, 1, 103, "優雅に浜を駆ける、真夏のマホ姫。しゃなりしゃなりと、雅な身のこなしで障害物を跳び越えていく。", 0, 0.013, 1, 107, 160, 7, 3.5, 0, 120);
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (110401, 8, 2, 103, "浜の平和を守る、真夏の狼娘。　　獣人の強靭なスタミナで、レース　後半にスパートをかける。", 1, 0.014, 0, 108, 350, 8, 2.5, 0, 110);
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (110501, 9, 3, 100, "浜に力強く舞う、真夏の南国娘。　レースの喧噪の中でも精神を乱さず後半に大きな捲りを見せる。", 0, 0.012, 0, 109, 130, 9, 1.5, 1, 105);
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (115701, 10, 1, 103, "浜の事件を嗅ぎ付けた、真夏の　　名探偵。高い推理力と魔法で、的確に対戦相手の走りを乱す。", 0, 0.014, 1, 110, 200, 10, 2.5, 0, 105);
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (113601, 11, 2, 103, "再び鎧を脱いだ、灼熱の騎士団長。実戦で培った判断力で、瞬時にバリアを展開し、障害物を無力化する。", 1, 0.071, 0, 111, 350, 11, 2.5, 0, 105);
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (107901, 12, 3, 103, "水が苦手な、海辺の気まぐれ猫娘。浜に現れた美少女義賊は、対戦相手のスピードを奪いとる。", 0, 0.014, 0, 112, 130, 12, 1.5, 1, 120);
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (108001, 13, 2, 105, "バカンスも効率第一な、海の傭兵。レースでも最高効率を求め、どんな状況でも隙のない走りを見せる。", 0, 0.022, 1, 113, 200, 13, 1.5, 0, 110);
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (110301, 14, 1, 108, "真夏の太陽が良く似合う、海辺の　サレンママ。多才で器用、どんな　障害物もエレガントに越えていく。", 0, 0.031, 1, 114, 160, 14, 2.5, 0, 110);
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (107701, 15, 1, 105, "海に嵐を呼ぶ夏のドジっ娘メイド。日頃から災難に慣れており、多少　のトラブルには動じたりしない。", 0, 0.036, 0, 115, 130, 15, 0.5, 1, 110);
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (113101, 16, 2, 95, "粋な夏を愉しむ、若夏の姉御。　　流麗な身体捌きで、始・継・終と、UBを重ねるごとに、加速する。", 1, 0.048, 0, 116, 350, 16, 3.5, 0, 110);
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (113301, 17, 3, 105, "夏のトキメキに触れた、オタク魔法少女。多彩な魔法を操り、少しずつ他の走者の速度を落とし続ける。", 0, 0.043, 0, 117, 130, 17, 1.5, 1, 105);
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (113201, 18, 2, 95, "海獄に降臨せし、真夏の冥姫。　　レース後半に魔力を全解放し、　　蒼き疾風と成りて浜を駆け抜ける。", 0, 0.018, 0, 118, 130, 18, 1.5, 1, 105);
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (117001, 19, 2, 108, "夏の夕を火花で彩る、渚の壊し屋。『壊し屋』の異名と過激な愛情は、対戦相手にプレッシャーを与える。", 0, 0.021, 1, 119, 160, 19, 2.5, 0, 110);
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (113501, 20, 1, 105, "青春に生きる者を導く、夏の先生。夢へと邁進する聖母の加護が、その身をあらゆる困難から守る。", 1, 0.036, 0, 120, 255, 20, 2.5, 0, 110);
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (113401, 21, 3, 105, "笑顔の応援が眩しい、夏の超能力　ガール。超能力を駆使して、どんな障害物もひとっ飛びで乗り越える。", 1, 0.02, 0, 121, 350, 21, 2.5, 0, 105);
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (110101, 22, 1, 105, "海辺で大人の魅力を放つ、夏の　　セクシー先生。その魅力に囚われた対戦相手は、走りを乱してしまう。", 0, 0.018, 0, 122, 130, 22, 2.5, 1, 110);
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (110001, 23, 3, 111, "水着も絶対外さない、夏のカリスマモデル。走りのバイブスは超テンアゲで、スピードはおにやば。", 0, 0.03, 1, 123, 160, 23, 3.5, 0, 105);
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (117201, 24, 1, 103, "南の島も盛り上げる、真夏のアイドル。悪天候でも笑顔を絶やさず後半もリズムを上げて走り切る。", 0, 0.027, 0, 124, 130, 24, 1.5, 1, 110);
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (117301, 25, 2, 108, "海原に美声を響かす、渚の歌姫。　守護の賛歌と精霊の加護により、　障害物から身を守る。", 0, 0.02, 1, 125, 160, 25, 3.5, 0, 105);
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (117401, 26, 3, 105, "夏でも天邪鬼な、夕凪のテーラー。張り巡らされた魔法の糸で、他の走者の自由を奪う。", 1, 0.04, 0, 126, 350, 26, 2.5, 0, 110);
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (117101, 27, 1, 105, "向日葵が良く似合う、海辺の　　　お姉ちゃん。秘密結社の一員で、　抜群の身体能力が一番の武器。", 1, 0.009, 0, 127, 350, 27, 3.5, 0, 110);
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (122901, 28, 1, 105, "渚でおっとり、夏色うさぎっこ。　うさぎさんパワー全開で、ぴょん　ぴょんとコースを跳ね回る。", 1, 0.022, 0, 128, 255, 28, 3.5, 0, 120);
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (122801, 29, 3, 105, "無邪気さ弾ける、夏色いたずら娘。砂浜でも、いたずらの準備は万端！レースに大波乱が巻き起こる！？", 0, 0.028, 0, 129, 130, 29, 2.5, 1, 110);
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (122701, 30, 2, 108, "海でも真面目な、夏色優等生。　　高めた魔力を解き放ち、一瞬の内に他の走者を置き去りにする。", 0, 0.023, 1, 130, 130, 30, 3.5, 0, 105);
